mapper.select:


    inner join sys_user u on u.user_name = tcheckareahistory.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tcheckareahistory.del_flag = '0'
     and tcheckareahistory.task_detail_id = #{taskDetailId}
     and tcheckareahistory.batch_number = #{batchNumber}
     and tcheckareahistory.tray_code like concat('%', #{trayCode}, '%')
     and tcheckareahistory.actual_count = #{actualCount}
     and tcheckareahistory.is_draft = #{isDraft}
     and tcheckareahistory.task_id = #{taskId}
     and tcheckareahistory.predict_count = #{predictCount}
     and tcheckareahistory.status = #{status}
     and tcheckareahistory.material_id = #{materialId}


${params.dataScope}
